  put('m2_proof', 6, 'fig', '<svg viewBox="0 0 220 176" class="lz-fig" role="img" aria-label="(a+b)³を展開するとき、3つのかっこのどの2つからbを選ぶかで3C2=3通りあり、ab²の係数は3になる"><text x="8" y="18">(a + b)(a + b)(a + b) で a b² の項</text><text x="70" y="40" text-anchor="middle">①</text><text x="110" y="40" text-anchor="middle">②</text><text x="150" y="40" text-anchor="middle">③</text><rect x="56" y="52" width="28" height="22" class="bx"/><text x="70" y="67" text-anchor="middle">a</text><rect x="96" y="52" width="28" height="22" class="fl"/><text x="110" y="67" text-anchor="middle">b</text><rect x="136" y="52" width="28" height="22" class="fl"/><text x="150" y="67" text-anchor="middle">b</text><text x="180" y="67">→ ab²</text><rect x="56" y="80" width="28" height="22" class="fl"/><text x="70" y="95" text-anchor="middle">b</text><rect x="96" y="80" width="28" height="22" class="bx"/><text x="110" y="95" text-anchor="middle">a</text><rect x="136" y="80" width="28" height="22" class="fl"/><text x="150" y="95" text-anchor="middle">b</text><text x="180" y="95">→ ab²</text><rect x="56" y="108" width="28" height="22" class="fl"/><text x="70" y="123" text-anchor="middle">b</text><rect x="96" y="108" width="28" height="22" class="fl"/><text x="110" y="123" text-anchor="middle">b</text><rect x="136" y="108" width="28" height="22" class="bx"/><text x="150" y="123" text-anchor="middle">a</text><text x="180" y="123">→ ab²</text><text x="8" y="74">b を</text><text x="8" y="90">選ぶ</text><text x="8" y="106">かっこ</text><text x="8" y="152">どの 2 つから b を選ぶか ₃C₂ = 3 通り</text><text x="8" y="168">→ 係数 3(3ab²)</text></svg>');
  put('m2_proof', 4, 'fig', '<svg viewBox="0 0 240 158" class="lz-fig" role="img" aria-label="b を固定して差 (a²+b²)−2ab=(a−b)² を a の関数と見たグラフ。0より下にならず、0になるのは a=b のときだけで、これが等号の条件"><line x1="18" y1="127.1" x2="150" y2="127.1" class="ax"/><line x1="29" y1="140" x2="29" y2="14" class="ax"/><text x="142" y="139.1">a</text><text x="33" y="24"></text><polyline points="26.8,17.9 29.1,26.4 31.4,34.7 33.7,42.5 36,50 38.2,57.2 40.5,64 42.8,70.5 45.1,76.6 47.4,82.3 49.7,87.8 52,92.8 54.3,97.5 56.5,101.9 58.8,105.9 61.1,109.6 63.4,112.9 65.7,115.9 68,118.5 70.3,120.8 72.6,122.7 74.8,124.3 77.1,125.5 79.4,126.4 81.7,126.9 84,127.1 86.3,126.9 88.6,126.4 90.9,125.5 93.2,124.3 95.4,122.7 97.7,120.8 100,118.5 102.3,115.9 104.6,112.9 106.9,109.6 109.2,105.9 111.5,101.9 113.7,97.5 116,92.8 118.3,87.8 120.6,82.3 122.9,76.6 125.2,70.5 127.5,64 129.8,57.2 132,50 134.3,42.5 136.6,34.7 138.9,26.4 141.2,17.9" class="cv"/><circle cx="84" cy="127.1" r="4" class="pt"/><text x="84" y="140.1" text-anchor="middle">a = b</text><line x1="121.4" y1="127.1" x2="121.4" y2="80.4" class="cv2"/><text x="125.4" y="104.5">差</text><text x="154" y="30">(a² + b²) − 2ab</text><text x="154" y="46">= (a − b)²</text><text x="154" y="74">グラフは</text><text x="154" y="90">x軸より下に</text><text x="154" y="106">出ない → ≧ 0</text><text x="154" y="134">0 になるのは</text><text x="154" y="150">a = b のとき</text></svg>');
  put('m2_complex', 1, 'fig', '<svg viewBox="0 0 240 158" class="lz-fig" role="img" aria-label="複素数1+2iを点で表すと、共役な複素数1−2iは実軸について折り返した点。2つをかけると1²+2²=5の実数になる"><line x1="14" y1="80" x2="150" y2="80" class="ax"/><line x1="77.1" y1="150" x2="77.1" y2="10" class="ax"/><text x="142" y="92">実</text><text x="81.1" y="20">虚</text><line x1="101.4" y1="30" x2="101.4" y2="130" class="dash"/><line x1="77.1" y1="80" x2="101.4" y2="30" class="cv"/><line x1="77.1" y1="80" x2="101.4" y2="130" class="cv2"/><circle cx="101.4" cy="30" r="4" class="pt"/><circle cx="101.4" cy="130" r="4" class="pt"/><text x="107.4" y="34">1 + 2i</text><text x="107.4" y="134">1 − 2i</text><text x="73.1" y="34" text-anchor="end">2</text><text x="73.1" y="134" text-anchor="end">−2</text><text x="101.4" y="93" text-anchor="middle">1</text><text x="154" y="30">共役:実軸で</text><text x="154" y="46">折り返した点</text><text x="154" y="80">(1+2i)(1−2i)</text><text x="154" y="96">= 1² + 2²</text><text x="154" y="112">= 5(実数)</text></svg>');
  put('m2_complex', 8, 'fig', '<svg viewBox="0 0 240 162" class="lz-fig" role="img" aria-label="x²+x+1=0の解ωと、1、ω、ω²を複素数平面にとった図。3点は半径1の円上に120°ずつ並び、ω³=1なので累乗は3つごとにくり返す"><line x1="20" y1="72" x2="152" y2="72" class="ax"/><line x1="86" y1="130" x2="86" y2="14" class="ax"/><text x="144" y="84">実</text><text x="90" y="24">虚</text><circle cx="86" cy="72" r="41.3" class="dash"/><polygon points="127.3,72 65.4,36.1 65.4,107.9" class="tr"/><circle cx="127.3" cy="72" r="4" class="pt"/><circle cx="65.4" cy="36.1" r="4" class="pt"/><circle cx="65.4" cy="107.9" r="4" class="pt"/><text x="131.3" y="66">1</text><text x="61.4" y="30.1" text-anchor="end">ω</text><text x="61.4" y="121.9" text-anchor="end">ω²</text><path d="M102 72 A16 16 0 0 0 78 58.1" class="arc"/><text x="94" y="56">120°</text><text x="158" y="30">ω = (−1 + √3 i)/2</text><text x="158" y="54">ω³ = 1</text><text x="158" y="70">1, ω, ω² を</text><text x="158" y="86">くり返す</text><text x="158" y="110">ω² + ω + 1 = 0</text><text x="8" y="152">ω¹⁰⁰ = ω、ω⁵⁰ = ω² → ω¹⁰⁰ + ω⁵⁰ + 1 = 0</text></svg>');
