  put('m_h5', 6, 'fig', '<svg viewBox="0 0 240 184" class="lz-fig" role="img" aria-label="単位円上の点P(cosθ, sinθ)を、x軸・y軸・原点について対称移動すると、角−θ、π−θ、θ+πの点になり、座標の符号の変わり方が分かる"><line x1="58" y1="82" x2="182" y2="82" class="ax"/><line x1="120" y1="20" x2="120" y2="144" class="ax"/><circle cx="120" cy="82" r="46" class="ax"/><line x1="120" y1="82" x2="157.7" y2="55.6" class="cv"/><line x1="157.7" y1="55.6" x2="157.7" y2="108.4" class="dash"/><line x1="157.7" y1="55.6" x2="82.3" y2="55.6" class="dash"/><line x1="157.7" y1="55.6" x2="82.3" y2="108.4" class="dash"/><circle cx="157.7" cy="55.6" r="4" class="pt"/><circle cx="157.7" cy="108.4" r="3.5" class="pt"/><circle cx="82.3" cy="55.6" r="3.5" class="pt"/><circle cx="82.3" cy="108.4" r="3.5" class="pt"/><path d="M134 82 A14 14 0 0 0 131.5 74" class="arc"/><text x="136" y="78">θ</text><text x="163.7" y="47.6">θ:(c, s)</text><text x="76.3" y="47.6" text-anchor="end">π − θ:(−c, s)</text><text x="76.3" y="124.4" text-anchor="end">θ + π:(−c, −s)</text><text x="163.7" y="124.4">−θ:(c, −s)</text><text x="8" y="160">c = cos θ、s = sin θ</text><text x="8" y="176">−θ は x軸、π−θ は y軸、θ+π は原点で対称</text></svg>');
  put('m2_addth', 8, 'fig', '<svg viewBox="0 0 240 158" class="lz-fig" role="img" aria-label="2直線y=3xとy=x/2がx軸となす角をα、βとすると、なす角θ=α−β。tanの加法定理でtanθ=1となりθ=π/4"><line x1="14" y1="141.1" x2="150" y2="141.1" class="ax"/><line x1="22.7" y1="150" x2="22.7" y2="10" class="ax"/><text x="142" y="153.1">x</text><text x="26.7" y="20">y</text><line x1="22.7" y1="141.1" x2="63.2" y2="16" class="cv"/><line x1="22.7" y1="141.1" x2="147.1" y2="77" class="cv2"/><path d="M76.4 114.3 A60 60 0 0 0 41.7 84.2" class="arc"/><path d="M48.7 141.1 A26 26 0 0 0 46 129.5" class="dash"/><path d="M62.7 141.1 A40 40 0 0 0 35.3 103.2" class="dash"/><text x="67.2" y="26">y = 3x</text><text x="145.1" y="69" text-anchor="end">y = x/2</text><text x="59.4" y="88.7">θ</text><text x="51.7" y="138.1">β</text><text x="52.7" y="113.1">α</text><text x="154" y="30">tan α = 3</text><text x="154" y="46">tan β = 1/2</text><text x="154" y="72">tan θ = tan(α − β)</text><text x="154" y="88">= (3 − 1/2)</text><text x="160" y="104">÷ (1 + 3/2)</text><text x="154" y="120">= 1</text><text x="154" y="140">→ θ = π/4</text></svg>');
  put('m2_addth', 9, 'fig', '<svg viewBox="0 0 240 160" class="lz-fig" role="img" aria-label="θ=18°のとき2θ=36°と3θ=54°の和は90°で、単位円上の2点は直線y=xについて対称。だからsin36°=cos54°、つまりsin2θ=cos3θ"><line x1="16" y1="120.9" x2="140" y2="120.9" class="ax"/><line x1="33.1" y1="138" x2="33.1" y2="14" class="ax"/><text x="132" y="132.9">x</text><text x="37.1" y="24">y</text><path d="M118.6 120.9 A85.5 85.5 0 0 0 33.1 35.4" class="ax"/><line x1="33.1" y1="120.9" x2="135.7" y2="18.3" class="dash"/><line x1="33.1" y1="120.9" x2="102.3" y2="70.6" class="cv"/><line x1="33.1" y1="120.9" x2="83.4" y2="51.7" class="cv2"/><line x1="102.3" y1="70.6" x2="102.3" y2="120.9" class="cv"/><line x1="83.4" y1="51.7" x2="83.4" y2="120.9" class="cv2"/><circle cx="102.3" cy="70.6" r="3.5" class="pt"/><circle cx="83.4" cy="51.7" r="3.5" class="pt"/><text x="107.3" y="72.6">36°</text><text x="85.4" y="45.7">54°</text><text x="133.7" y="32.3" text-anchor="end">y = x</text><text x="105.3" y="101.8">sin36°</text><text x="80.4" y="133.9" text-anchor="end">cos54°</text><text x="150" y="30">θ = 18° のとき</text><text x="150" y="46">2θ + 3θ = 90°</text><text x="150" y="72">2つの点は</text><text x="150" y="88">y = x で対称</text><text x="150" y="112">sin 2θ = cos 3θ</text><text x="150" y="136">sin 18°</text><text x="150" y="152">= (√5 − 1)/4</text></svg>');
